# count components debug
h,w=len(D1),len(D1[0]); seen=set(); comps=[]
for r in range(h):
 for c in range(w):
  color=D1[r][c]
  if color==8 or (r,c) in seen: continue
  pts=[]; seen.add((r,c)); st=[(r,c)]
  while st:
   y,x=st.pop();pts.append((y,x))
   for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
    ny,nx=y+dy,x+dx
    if 0<=ny<h and 0<=nx<w and (ny,nx) not in seen and D1[ny][nx]==color:
     seen.add((ny,nx));st.append((ny,nx))
  comps.append((color,len(pts),min(y for y,x in pts),min(x for y,x in pts)))
print(comps)
